function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 500) return 'nums needs 2 to 500 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is an integer from 1 to 1000.';
  return null;
}

