function maxProduct(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  const n = sorted.length;
  const largest = sorted[n - 1];
  const second = sorted[n - 2];
  const product = (largest - 1) * (second - 1);
  return product;
}

