function maxProduct(nums) {
  let answer = -Infinity;
  for (let i = 0; i < nums.length; i++)
    for (let j = 0; j < nums.length; j++)
      if (i !== j) answer = Math.max(answer, (nums[i] - 1) * (nums[j] - 1));
  return answer;
}

